function render(){const raw=decodeURIComponent(location.hash.slice(1)||'/');const path=raw.split('?')[0];let content;if(path==='/')content=home();else if(path==='/work')content=work();else if(path.startsWith('/work/'))content=workDetail(path.split('/')[2]);else if(path==='/about')content=about();else if(path==='/contact')content=contact();else if(path==='/resume')content=resume();else content=notFound();document.getElementById('app').innerHTML=header(path)+`<main id="main" tabindex="-1">${content}</main>`+footer();document.title=(path==='/'?'Sued R. Mwaigomole':path.split('/').filter(Boolean).map(s=>s.replaceAll('-',' ')).join(' · '))+' | Living Portfolio';const theme=localStorage.getItem('portfolio-theme');document.documentElement.dataset.theme=theme==='dark'?'dark':'light';document.getElementById('theme-btn').onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('portfolio-theme',next)};document.getElementById('menu-btn').onclick=()=>{const l=document.getElementById('nav-links');const open=l.classList.toggle('open');document.getElementById('menu-btn').setAttribute('aria-expanded',String(open))};document.querySelectorAll('.links a').forEach(a=>a.addEventListener('click',()=>document.getElementById('nav-links').classList.remove('open')));document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('work-results').innerHTML=projects.filter(p=>b.dataset.filter==='All'||p.category===b.dataset.filter).map(workCard).join('')});const copy=document.getElementById('copy-email');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText(EMAIL);toast('Email copied to clipboard')}catch{toast('Copy this email: '+EMAIL)}};const print=document.getElementById('print-resume');if(print)print.onclick=()=>window.print();window.scrollTo({top:0,behavior:'instant'})}
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),3500)}
